f=@(x)1./(1+25.*(x.^2));
f_prime=@(x)-50.*x./((1+25.*(x.^2)).^2);
vl = f_prime(-1);
vr = f_prime(1);
mesh = linspace(-1,1,1000);
for i=1:2
    if i == 1
        n = 5;  % Per Brandon's suggestion
    else
        n = 12;
    end
    Xi = linspace(-1,1,n);
    Yi = f(Xi);
    cs = spline(Xi, [vl Yi vr]);
    Ps = ppval(cs, mesh);
    figure();
    plot(Xi, Yi, 'bo');
    hold on;
    plot(mesh, Ps, 'r-');
    hold on;
    plot(mesh, f(mesh), 'k-');
    hold on;
    legend("Nodes", "Splines", "Real Function");
    title("Problem 1 for n=" + n);
end
